# Instead do direct brute force over 8 dihedral ops composed with translation offsets. Simpler: brute-force over all 8 dihedral transforms T_op applied to whole grid + translation t, requiring mapping of every non-8 cell into a non-8 cell with same value.
import itertools
def dih(w):
    yield w; yield w[:,::-1]; yield w[::-1,:]; yield w[::-1,::-1]
    yield w.T; yield w.T[:,::-1]; yield w.T[::-1,:]; yield w.T[::-1,::-1]
found_ops=[]
for di,dof in enumerate(dih(Ia)):
    ph,pw=dof.shape
    for dr in range(-ph,H-ph+1):
        for dc in range(-pw,W-pw+1):
            ok=True
            for r in range(H):
                for c in range(W):
                    if Ia[r,c]!=8:
                        rr,cc=r+dr,c+dc
                        if not(0<=rr<H and 0<=cc<W) or dof[rr-dr,cc-dc]!=Ia[r,c]: ok=False;break
                if not ok:break
            if ok and any(0<=r+dr<H and 0<=c+dc<W and Ia[r+dr,c+dc]==8 for r in range(rb0,rb1+1) for c in range(cb0,cb1+1)) and not any(0<=r+dr<H and 0<=c+dc<W and Ia[r+dr,c+dc]==8 for r in range(H) for c in range(W) if Ia[r,c]!=8):
